import{Z as t,e as a,f as i,a0 as o}from"./chunks/framework.DmpHOl9T.js";const h=JSON.parse('{"title":"Calculations Field in Detail","description":"","frontmatter":{},"headers":[],"relativePath":"guides/fields/calculations-field-in-detail.md","filePath":"guides/fields/calculations-field-in-detail.md","lastUpdated":1782532814000}'),s={name:"guides/fields/calculations-field-in-detail.md"};function d(n,e,l,c,r,p){return a(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="calculations-field-in-detail" tabindex="-1">Calculations Field in Detail <a class="header-anchor" href="#calculations-field-in-detail" aria-label="Permalink to &quot;Calculations Field in Detail&quot;">​</a></h1><p>This guide walks through Calculations syntax, field references, built-in functions, and practical examples. Use it alongside the <a href="/fields/calculations">Calculations field reference</a> when you are building pricing, scoring, or conditional output on a form.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>At least one <a href="/fields/calculations">Calculations field</a> on a form</li><li>Other fields whose values the formula will reference (Number fields work best for arithmetic)</li></ul><h2 id="field-references" tabindex="-1">Field References <a class="header-anchor" href="#field-references" aria-label="Permalink to &quot;Field References&quot;">​</a></h2><p>Always insert references with the variable picker in the formula editor. Formie stores stable tokens — not raw handles:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{field:a1b2c3}</span></span></code></pre></div><p>Do not type <code>{myFieldHandle}</code> manually. The token ID is generated when the field is created and stays stable even if you rename the handle.</p><h3 id="sub-values-and-selectors" tabindex="-1">Sub-Values and Selectors <a class="header-anchor" href="#sub-values-and-selectors" aria-label="Permalink to &quot;Sub-Values and Selectors&quot;">​</a></h3><p>When a field exposes multiple referenceable values, add a selector:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{field:a1b2c3:firstName}</span></span>
<span class="line"><span>{field:a1b2c3:lastName}</span></span></code></pre></div><p>Concatenate name parts:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{field:a1b2c3:firstName} ~ &quot; &quot; ~ {field:a1b2c3:lastName}</span></span></code></pre></div><h3 id="table-columns-and-row-scope" tabindex="-1">Table Columns and Row Scope <a class="header-anchor" href="#table-columns-and-row-scope" aria-label="Permalink to &quot;Table Columns and Row Scope&quot;">​</a></h3><p>Table fields expose each column separately. Pick the column in the variable picker, then choose which rows to read:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{field:a1b2c3:col3;scope=first}</span></span>
<span class="line"><span>{field:a1b2c3:col3;scope=all}</span></span>
<span class="line"><span>{field:a1b2c3:col3;scope=custom;rows=1,2,3}</span></span></code></pre></div><p>To total a numeric column across all rows, use <strong>All rows</strong> scope in the picker — Formie sums numeric column values before they enter the formula.</p><h2 id="operators" tabindex="-1">Operators <a class="header-anchor" href="#operators" aria-label="Permalink to &quot;Operators&quot;">​</a></h2><p>Calculations use <a href="https://symfony.com/doc/current/reference/formats/expression_language.html" target="_blank" rel="noreferrer">Symfony Expression Syntax</a>. <strong>Twig is not supported.</strong></p><h3 id="arithmetic" tabindex="-1">Arithmetic <a class="header-anchor" href="#arithmetic" aria-label="Permalink to &quot;Arithmetic&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Operator</th><th>Meaning</th></tr></thead><tbody><tr><td><code>+</code></td><td>Addition</td></tr><tr><td><code>-</code></td><td>Subtraction</td></tr><tr><td><code>*</code></td><td>Multiplication</td></tr><tr><td><code>/</code></td><td>Division</td></tr><tr><td><code>%</code></td><td>Modulus</td></tr><tr><td><code>**</code></td><td>Power</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>({field:a1b2c3} * 50) + ({field:d4e5f6} * 25)</span></span></code></pre></div><h3 id="comparison-and-logic" tabindex="-1">Comparison and Logic <a class="header-anchor" href="#comparison-and-logic" aria-label="Permalink to &quot;Comparison and Logic&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Operator</th><th>Meaning</th></tr></thead><tbody><tr><td><code>==</code> / <code>!=</code></td><td>Equal / not equal</td></tr><tr><td><code>&lt;</code> / <code>&gt;</code> / <code>&lt;=</code> / <code>&gt;=</code></td><td>Comparisons</td></tr><tr><td><code>and</code> / <code>&amp;&amp;</code></td><td>And</td></tr><tr><td><code>or</code> / <code>||</code></td><td>Or</td></tr><tr><td><code>not</code> / <code>!</code></td><td>Not</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{field:a1b2c3} &gt; 10 and {field:d4e5f6} &lt; 100</span></span></code></pre></div><p>Also supported: strict comparisons (<code>===</code>, <code>!==</code>), regex <code>matches</code>, <code>in</code> / <code>not in</code>, ranges with <code>..</code>, and bitwise operators.</p><h3 id="ternary-and-concatenation" tabindex="-1">Ternary and Concatenation <a class="header-anchor" href="#ternary-and-concatenation" aria-label="Permalink to &quot;Ternary and Concatenation&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{field:a1b2c3} &gt;= 10 ? {field:a1b2c3} * {field:d4e5f6} * 0.9 : {field:a1b2c3} * {field:d4e5f6}</span></span></code></pre></div><p>Use <code>~</code> for string concatenation.</p><h2 id="built-in-functions" tabindex="-1">Built-in Functions <a class="header-anchor" href="#built-in-functions" aria-label="Permalink to &quot;Built-in Functions&quot;">​</a></h2><p>Formie registers these functions in addition to Symfony&#39;s defaults:</p><table tabindex="0"><thead><tr><th>Function</th><th>Example</th><th>Purpose</th></tr></thead><tbody><tr><td><code>contains(subject, pattern)</code></td><td><code>contains({field:a1b2c3}, &quot;vip&quot;)</code></td><td>True if text contains pattern, or array contains value</td></tr><tr><td><code>notContains(subject, pattern)</code></td><td><code>notContains({field:a1b2c3}, &quot;test&quot;)</code></td><td>Inverse of <code>contains</code></td></tr><tr><td><code>startsWith(subject, pattern)</code></td><td><code>startsWith({field:a1b2c3}, &quot;http&quot;)</code></td><td>True if text starts with pattern</td></tr><tr><td><code>endsWith(subject, pattern)</code></td><td><code>endsWith({field:a1b2c3}, &quot;.com&quot;)</code></td><td>True if text ends with pattern</td></tr><tr><td><code>empty(subject)</code></td><td><code>empty({field:a1b2c3})</code></td><td>True for null, blank strings, empty arrays</td></tr><tr><td><code>notEmpty(subject)</code></td><td><code>notEmpty({field:a1b2c3})</code></td><td>Inverse of <code>empty</code></td></tr><tr><td><code>sum(value)</code></td><td><code>sum({field:a1b2c3})</code></td><td>Sum of array values, or numeric passthrough</td></tr></tbody></table><p>Combine functions with ternary logic:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>notEmpty({field:a1b2c3}) ? {field:a1b2c3} * 1.1 : 0</span></span></code></pre></div><h2 id="how-values-are-coerced" tabindex="-1">How Values Are Coerced <a class="header-anchor" href="#how-values-are-coerced" aria-label="Permalink to &quot;How Values Are Coerced&quot;">​</a></h2><p>On the front end, Formie casts numeric-looking strings to numbers before evaluation so <code>1 + 2</code> equals <code>3</code>, not <code>12</code>. Empty Number field values become <code>0</code>. Checkbox values arrive as arrays; when every item is numeric, Formie may sum them for use in arithmetic.</p><p>Text and Email fields can be referenced, but treat them as text unless you know the submitted value is always numeric.</p><h2 id="formatting-the-result" tabindex="-1">Formatting the Result <a class="header-anchor" href="#formatting-the-result" aria-label="Permalink to &quot;Formatting the Result&quot;">​</a></h2><p>Use the Calculations field settings before reaching for custom JavaScript:</p><ul><li><strong>Prefix / suffix</strong> — currency symbols, units (<code>$</code>, <code> kg</code>)</li><li><strong>Number formatting</strong> — decimal places, rounding</li><li><strong>Visibility</strong> — hide the calculated value from the user while still storing it</li></ul><p>When display formatting needs locale-specific currency or custom rounding, use the <a href="/guides/fields/write-your-own-parsing-logic-for-the-calculations-field">before/after evaluate events</a>.</p><h2 id="worked-examples" tabindex="-1">Worked Examples <a class="header-anchor" href="#worked-examples" aria-label="Permalink to &quot;Worked Examples&quot;">​</a></h2><h3 id="simple-line-total" tabindex="-1">Simple Line Total <a class="header-anchor" href="#simple-line-total" aria-label="Permalink to &quot;Simple Line Total&quot;">​</a></h3><p>Number field <code>quantity</code>, Number field <code>unitPrice</code>, Calculations field <code>lineTotal</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{field:qty} * {field:price}</span></span></code></pre></div><p>Set number formatting to 2 decimal places and prefix <code>$</code>.</p><h3 id="volume-discount" tabindex="-1">Volume Discount <a class="header-anchor" href="#volume-discount" aria-label="Permalink to &quot;Volume Discount&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{field:qty} &gt;= 10 ? {field:qty} * {field:price} * 0.9 : {field:qty} * {field:price}</span></span></code></pre></div><h3 id="conditional-label" tabindex="-1">Conditional Label <a class="header-anchor" href="#conditional-label" aria-label="Permalink to &quot;Conditional Label&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{field:score} &gt;= 70 ? &quot;Pass&quot; : &quot;Retake required&quot;</span></span></code></pre></div><h3 id="shipping-tier" tabindex="-1">Shipping Tier <a class="header-anchor" href="#shipping-tier" aria-label="Permalink to &quot;Shipping Tier&quot;">​</a></h3><p>Dropdown field <code>region</code> with values <code>local</code>, <code>national</code>, <code>international</code>; Number field <code>weight</code>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>{field:region} == &quot;local&quot; ? 5 : ({field:region} == &quot;national&quot; ? 12 : 25 + {field:weight} * 2)</span></span></code></pre></div><h2 id="submitted-value-and-integrations" tabindex="-1">Submitted Value and Integrations <a class="header-anchor" href="#submitted-value-and-integrations" aria-label="Permalink to &quot;Submitted Value and Integrations&quot;">​</a></h2><p>Calculations stores the computed result at submit time. Treat it as derived output in exports, notifications, and CRM mappings — not as user-entered input.</p><p>If a formula depends on external APIs, complex branching, or data outside the form, custom code or an integration is usually easier to maintain than an enormous expression.</p>`,56)])])}const b=t(s,[["render",d]]);export{h as __pageData,b as default};
